import{_ as t,o as r,c as s,j as a,a as l}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/81-焦虑——回避型伴侣间的性爱.md","filePath":"books/attached/81-焦虑——回避型伴侣间的性爱.md","lastUpdated":1794298621000}'),n={name:"books/attached/81-焦虑——回避型伴侣间的性爱.md"};function o(_,e,d,c,p,i){return r(),s("div",null,[...e[0]||(e[0]=[a("h3",{id:"焦虑——回避型伴侣间的性爱",tabindex:"-1"},[l("焦虑——回避型伴侣间的性爱 "),a("a",{class:"header-anchor",href:"#焦虑——回避型伴侣间的性爱","aria-label":'Permalink to "焦虑——回避型伴侣间的性爱"'},"​")],-1),a("p",null,"我们注意到，玛莎对克雷格的描述是“我所有男朋友中，发生性关系次数最少的一个”。回避型依恋风格的人，常常会在性关系上与对方保持距离。这倒不是说他们在有意欺骗玩弄伴侣，只是研究表明相比于其他依恋风格，回避型依恋风格的人这样做的概率比较高。菲利普·谢弗在一项与加州大学戴维斯分校的学生多利·沙赫纳（Dory Schachner）合作的研究中，发现在三种依恋风格中，回避型是最容易在自己有伴侣时与他人产生纠葛的，即使没有付诸行动，产生这种动机的概率也是最高。",-1),a("p",null,"另外，即使回避型伴侣的确是忠诚的，他们也会通过其他办法，在性关系上与对方保持距离。相比于焦虑型依恋风格的人非常喜欢在亲热的时候产生强烈的情绪，并且增加很多诸如亲吻、爱抚这样的亲密举动，回避型的人群的偏好就截然不同。他们可能会选择仅仅关注性爱本身，仅仅是进行拥抱与依偎，甚至形成一些原则，比如说在性爱的时候坚持不接吻，以此来减低性爱产生的亲密感。还有一些人会减少与伴侣的性爱次数，甚至拒绝性爱或者在做爱的时候幻想他人。（有的情侣的确会在交往比较久的情况下，通过幻想来增添性爱的情趣。但对于回避型人群来说，这种幻想并不是为了获得心理满足，而是以此作为去激活策略，将彼此孤立开来。）事实上在加拿大科学家奥黛丽·布拉萨德（Audrey Brassard）和伊万·卢西耶（Yvan Lussier）与菲利普·谢弗合作的一项研究中发现，不论男女，相比于其他依恋风格，回避型人群与伴侣的性爱频率都比较低。",-1),a("p",null,"而吊诡的是，如果回避型人群的伴侣恰好是焦虑型，他们的性爱次数会尤其低！研究者认为，以玛莎和克雷格的关系为例，焦虑型的一方强烈要求身体上的亲密接触，但回避型的一方就会因此而节节后退。而减少性爱次数，显然是逃避亲密接触最有效的方式了。",-1),a("p",null,"另外，研究还发现焦虑型人群会将性爱当作确认关系稳定的手段，并且通过伴侣的眼神来测定对方是否足够深情。而当焦虑型人群如此看重性爱体验，回避型伴侣又如此逃避亲密时，两者的冲突就变得非常尖锐了。",-1),a("p",null,"当然，也有一些焦虑——回避型亲密关系中，性爱问题并不很棘手的情况，这时候情感上的分歧就会以另一种方式表现出来。",-1),a("p",null,"但是，在玛莎与克雷格在一起期间，性爱并不是最为棘手的问题。这只是克雷格所用的去激活策略中很小的一个部分，而他每天在人前人后所用的类似手段还有很多很多。简言之，克雷格将玛莎当作敌人一样地提防着，一反旁人看到的那种深情而体贴的形象。这种极大的反差，令玛莎十分困惑。玛莎可以说是克雷格在世上最亲近的人之一，他却将最深的伤痛带给了她。那他到底为什么在人前极好相处，却独独对玛莎如此刻薄呢？玛莎当时没有多想原因，只是相信只要自己让克雷格发觉了对她的伤害，就会幡然醒悟，像对待其他人一样地善待她。",-1),a("p",null,"可玛莎没有意识到，克雷格对他如此恶劣，并非因为自己不够亲近，而正是因为太过亲近。她已经进入了克雷格的亲密关系圈。一旦伴侣进入了我们的亲密关系圈，我们就会以对待至亲的独特方式来对待他们，这个圈子通常包括配偶和子女，父母与兄弟姐妹。而对于焦虑——回避型伴侣来说，亲密关系圈并不意味着十全十美。一旦玛莎越过这个圈子的界限，克雷格会因为这种令人不适的过分亲密，而像敌人一样提防着她。玛莎越想靠近，克雷格就越想将她推开。这种情况在焦虑——回避型亲密关系中，是十分常见的。",-1)])])}const m=t(n,[["render",o]]);export{h as __pageData,m as default};
